from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
import math

from virvision.scene import VisualScene


KCS_VERSION = "KCS-1"
DETAIL_LEVELS = ("compact", "balanced", "detailed")
OUTPUT_LANGUAGES = ("tr", "en")


class Phase(str, Enum):
    F0 = "F0"
    B0 = "B0"
    P0 = "P0"
    S0 = "S0"


class Region(str, Enum):
    UPPER_LEFT = "upper_left"
    UPPER_CENTER = "upper_center"
    UPPER_RIGHT = "upper_right"
    CENTER_LEFT = "center_left"
    CENTER = "center"
    CENTER_RIGHT = "center_right"
    LOWER_LEFT = "lower_left"
    LOWER_CENTER = "lower_center"
    LOWER_RIGHT = "lower_right"


@dataclass(frozen=True)
class RegionMark:
    entity_id: str
    entity_kind: str
    region: Region

    def __post_init__(self) -> None:
        if self.entity_kind not in {"unit", "trace"}:
            raise ValueError("entity_kind must be unit or trace")
        if not isinstance(self.region, Region):
            raise ValueError("region must be a Region")


@dataclass(frozen=True)
class Edge:
    source: str
    predicate: str
    target: str
    certainty: float
    source_kind: str
    target_kind: str

    def __post_init__(self) -> None:
        if not self.source or not self.target or self.source == self.target:
            raise ValueError("edge endpoints must be distinct nonempty identifiers")
        if not isinstance(self.predicate, str) or not self.predicate.strip():
            raise ValueError("edge predicate must be a nonempty string")
        if self.source_kind not in {"unit", "trace"} or self.target_kind not in {
            "unit",
            "trace",
        }:
            raise ValueError("edge endpoint kinds must be unit or trace")
        if (
            isinstance(self.certainty, bool)
            or not isinstance(self.certainty, (int, float))
            or not math.isfinite(self.certainty)
            or not 0 <= self.certainty <= 1
        ):
            raise ValueError("edge certainty must be finite and within [0,1]")

    def to_dict(self) -> dict:
        return {
            "source": self.source,
            "predicate": self.predicate,
            "target": self.target,
            "geometric_certainty": self.certainty,
            "source_kind": self.source_kind,
            "target_kind": self.target_kind,
        }


@dataclass(frozen=True)
class Field:
    scene: VisualScene
    regions: tuple[RegionMark, ...]
    edges: tuple[Edge, ...]
    phase: Phase = Phase.B0

    def __post_init__(self) -> None:
        if not isinstance(self.scene, VisualScene):
            raise ValueError("field scene must be a VisualScene")
        if any(not isinstance(item, RegionMark) for item in self.regions):
            raise ValueError("field regions must contain RegionMark values")
        if any(not isinstance(item, Edge) for item in self.edges):
            raise ValueError("field edges must contain Edge values")
        if self.phase is not Phase.B0:
            raise ValueError("bound Field phase must be B0")

    def region_of(self, entity_id: str) -> Region | None:
        for mark in self.regions:
            if mark.entity_id == entity_id:
                return mark.region
        return None


@dataclass(frozen=True)
class TextProjection:
    sentences: tuple[str, ...]
    language: str
    detail: str
    warnings: tuple[str, ...] = ()
    phase: Phase = Phase.P0

    def __post_init__(self) -> None:
        if self.language not in OUTPUT_LANGUAGES:
            raise ValueError("language must be tr or en")
        if self.detail not in DETAIL_LEVELS:
            raise ValueError("detail must be compact, balanced or detailed")
        if any(not isinstance(item, str) or not item.strip() for item in self.sentences):
            raise ValueError("projection sentences must be nonempty strings")
        if any(not isinstance(item, str) or not item for item in self.warnings):
            raise ValueError("projection warnings must be nonempty strings")
        if self.phase is not Phase.P0:
            raise ValueError("text projection phase must be P0")


@dataclass(frozen=True)
class KCSMetrics:
    edge_ms: float
    projection_ms: float
    surface_ms: float
    runtime_total_ms: float
    runtime_overhead_ms: float

    def to_dict(self) -> dict:
        return {
            "edge_ms": self.edge_ms,
            "projection_ms": self.projection_ms,
            "surface_ms": self.surface_ms,
            "runtime_total_ms": self.runtime_total_ms,
            "runtime_overhead_ms": self.runtime_overhead_ms,
        }


@dataclass(frozen=True)
class KCSRun:
    text: str
    field: Field
    projection: TextProjection
    metrics: KCSMetrics
    phase: Phase = Phase.S0
